import{_ as t,o as a,c as o,a5 as n}from"./chunks/framework.CsGesDJn.js";const y=JSON.parse('{"title":"3.4.2 View Agency Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-2-view-agency-dashboard/spec.md","filePath":"feature/agency-workspace/3-4-2-view-agency-dashboard/spec.md"}'),i={name:"feature/agency-workspace/3-4-2-view-agency-dashboard/spec.md"};function s(r,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_3-4-2-view-agency-dashboard" tabindex="-1">3.4.2 View Agency Dashboard <a class="header-anchor" href="#_3-4-2-view-agency-dashboard" aria-label="Permalink to &quot;3.4.2 View Agency Dashboard&quot;">​</a></h1><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Proposed — not yet implemented. The intended trigger is the Owner opening the dashboard of one of their Agencies (<code>/agencies/:agencyId/dashboard</code>). No dashboard screen exists in the current system.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Agency Owner. Proposed — not yet implemented.</li><li><strong>Purpose:</strong> Give the Owner an overview of one Agency — how many Workspaces and Members it has, how many Clients it serves, and what happened recently.</li><li><strong>Interface:</strong> Agency Dashboard page (<code>/agencies/:agencyId/dashboard</code>) — proposed; not yet implemented.</li><li><strong>Data Processing:</strong> The system would count the Members of the Agency, count the Workspaces belonging to it, count the distinct Clients across those Workspaces, and return them with a recent-activity list. Only the Member count can be derived from existing data today; the Workspace and Client counts and the recent-activity list still need to be designed.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Agency Dashboard:</p><ul><li>Summary tiles for Workspace count, Member count and Client count.</li><li>A recent-activity list.</li><li>Proposed — not yet implemented; the layout is indicative only.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Agency identifier (<code>agencyId</code>).</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> Agency profile (see 3.4.1 and 3.4.4), the Agency Member records of the Agency, the Workspaces belonging to the Agency, and the Client Profile records of those Workspaces. Recent activity has no agreed data source yet.</li><li><strong>Output:</strong> Proposed — a summary holding the Workspace count, the Member count and the Client count, together with a recent-activity list. Not yet implemented.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-29 (approximated):</strong> Multi-tenancy — only the Owner of the Agency may view its dashboard; anybody else is refused with <code>403 FORBIDDEN</code>, mirroring the workspace-scoped access rule since no Agency-dashboard-specific BR exists yet. <em>(No exact BR-xx covers a not-yet-implemented dashboard; closest fit noted.)</em></li><li>The Agency must exist and must not be soft-deleted; otherwise <code>404 AGENCY_NOT_FOUND</code>.</li><li>The Member count covers every Agency Member record of the Agency, whatever the role.</li><li>Proposed — not yet implemented: the Workspace and Client counts, and the recent-activity list, still have to be defined.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Caller is not the Agency Owner → Display: MSG39</li><li>Agency does not exist or is soft-deleted → Display: MSG38</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The Owner opens the Agency Dashboard. <em>(Proposed — not yet implemented.)</em></li><li>The client requests the dashboard summary for the Agency.</li><li>The system confirms that the Agency exists and that the caller is its Owner.</li><li>The system counts the Members of the Agency, its Workspaces, and the distinct Clients across those Workspaces, and collects the recent activity.</li><li>The system returns the summary and the client renders it.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: Caller is not the Agency Owner → <code>403 FORBIDDEN</code>, toast MSG39. 3.a2: The caller returns to the Agency list and opens an Agency they own.</li><li>3.b1: Agency does not exist or is soft-deleted → <code>404 AGENCY_NOT_FOUND</code>, toast MSG38. 3.b2: The caller returns to the Agency list.</li><li>4.a1: Agency just created, with no Workspace yet → every count is returned as zero, which is not an error; no toast shown. 4.a2: The Owner proceeds to create a Workspace to start populating the dashboard.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>No Agency data is created, changed or removed. <em>(Proposed — not yet implemented.)</em></li></ul>',22)])])}const g=t(i,[["render",s]]);export{y as __pageData,g as default};
